]);

function tripLength(roads, stops) {
  let total = 0;
  for (let i = 1; i < stops.length; i++) {
    const km = roads.get(stops[i - 1])?.get(stops[i]);
    if (km === undefined) throw new Error(`no road from ${stops[i - 1]} to ${stops[i]}`);
    total += km;
  }
  return total;
}

