  db: ["config", "logger"],
  config: [], logger: [], money: [], invoices: ["money"],
};

function transitiveDeps(uses, start) {
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length > 0) {
    for (const dep of uses[stack.pop()]) {
      if (!seen.has(dep)) {
        seen.add(dep);
        stack.push(dep);
      }
    }
  }
  seen.delete(start);
  return seen;
}

