function buildOrder(uses) {
  const needs = new Map(Object.keys(uses).map((name) => [name, []]));
  const inDegree = new Map(Object.keys(uses).map((name) => [name, uses[name].length]));
  for (const [name, deps] of Object.entries(uses)) {
    for (const dep of deps) needs.get(dep).push(name);
  }
  const queue = [...needs.keys()].filter((name) => inDegree.get(name) === 0);
  const order = [];
  for (let head = 0; head < queue.length; head++) {
    const name = queue[head];
    order.push(name);
    for (const user of needs.get(name)) {
      inDegree.set(user, inDegree.get(user) - 1);
      if (inDegree.get(user) === 0) queue.push(user);
    }
  }
  const blocked = [...needs.keys()].filter((name) => inDegree.get(name) > 0);
  return { order, blocked };
}

const ok = buildOrder({ api: ["auth", "db"], auth: ["db"], db: [], money: [] });
console.log(ok.order.join(" "), "| blocked:", ok.blocked.join(" "));

const broken = buildOrder({ api: ["auth"], auth: ["db"], db: ["auth"], money: [] });
console.log(broken.order.join(" "), "| blocked:", broken.blocked.join(" "));

