function findCycle(uses) {
  const state = new Map();
  const path = [];
  function visit(name) {
    if (state.get(name) === "done") return null;
    if (state.get(name) === "active") return [...path.slice(path.indexOf(name)), name];
    state.set(name, "active");
    path.push(name);
    for (const dep of uses[name] ?? []) {
      const found = visit(dep);
      if (found) return found;
    }
    path.pop();
    state.set(name, "done");
    return null;
  }
  for (const name of Object.keys(uses)) {
    const found = visit(name);
    if (found) return found;
  }
  return null;
}

