  orders: ["catalog", "money"],
  catalog: ["money"],
  auth: ["users"],
  users: [],
  invoices: ["money"],
  money: [],
};

function affected(uses, changed) {
  const usedBy = new Map(Object.keys(uses).map((name) => [name, []]));
  for (const [name, deps] of Object.entries(uses)) {
    for (const dep of deps) usedBy.get(dep).push(name);
  }
  const seen = new Set();
  const stack = [changed];
  while (stack.length > 0) {
    for (const user of usedBy.get(stack.pop())) {
      if (!seen.has(user)) {
        seen.add(user);
        stack.push(user);
      }
    }
  }
  return seen;
}

