};

function reachable(start) {
  const seen = new Set([start]);
  const stack = [start];
  while (stack.length > 0) {
    for (const next of oneWay[stack.pop()]) {
      if (!seen.has(next)) {
        seen.add(next);
        stack.push(next);
      }
    }
  }
  return seen.size - 1;
}

